local k={153,240,64,119,175,141,221,2,185,236,151,85,121,172,8,193,75,195,219,72,77,46,118,181,254,35,79,52,69,87,71,73}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
